class Task:
    def __init__(self, period, execution_time_distribution, worst_case_execution_time):
        self.p = period
        self.G = execution_time_distribution
        self.e = worst_case_execution_time

class TaskSystem:
    def __init__(self, tasks, num_processors):
        self.tasks = tasks
        self.m = num_processors

class Job:
    def __init__(self, task, job_index, release_time, execution_time):
        self.task = task
        self.j = job_index
        self.r = release_time
        self.d = release_time + task.p
        self.X = execution_time
        self.is_active = False
        self.is_eligible = False

def update_job_status(job, current_time):
    if job.r <= current_time and not job.is_finished:
        job.is_active = True
        if job.j == 1 or job.predecessor.is_finished:
            job.is_eligible = True
        else:
            job.is_eligible = False
    else:
        job.is_active = False
        job.is_eligible = False

def is_stable(task_system):
    total_expected_utilization = 0
    for task in task_system.tasks:
        expected_utilization = task.mean_execution_time / task.p
        if expected_utilization >= 1:
            return False
        total_expected_utilization += expected_utilization
    return total_expected_utilization < task_system.m

def is_schedulable(task_system, scheduler):
    # This is a high-level concept, actual check depends on the scheduler's analysis
    # For this paper, it means E[T_GEDF_i,j] is bounded for all i, j
    return scheduler.has_bounded_expected_tardiness(task_system)

class ProcessorSharingScheduler:
    def __init__(self, task_system):
        self.tasks = task_system.tasks
        self.m = task_system.m
        self.allocations = self.calculate_allocations()

    def calculate_allocations(self):
        # This is a conceptual step; actual calculation depends on specific u_i values
        # The paper implies u_i are chosen such that sum(u_i) <= m and u_i < 1
        allocations = {}
        # Example: if sum(task.mean_execution_time / task.p) < m:
        #    allocations = {task: task.mean_execution_time / task.p for task in self.tasks}
        #    # Adjust to satisfy u_i < 1 and sum(u_i) <= m
        return allocations

    def get_processing_rate(self, task):
        if task in self.allocations:
            return self.allocations[task]
        return 0

def compare_jobs_for_priority(job1, job2):
    # job1 = (job_instance1, task1)
    # job2 = (job_instance2, task2)
    if job1[0].d < job2[0].d:
        return -1 # job1 has higher priority
    elif job1[0].d > job2[0].d:
        return 1  # job2 has higher priority
    else:
        if job1[1].index < job2[1].index:
            return -1 # job1 has higher priority
        else:
            return 1  # job2 has higher priority

def calculate_lag(task, time_t, ps_allocations, gedf_allocations):
    lag_i = ps_allocations.get(task, 0) - gedf_allocations.get(task, 0)
    return lag_i

def calculate_total_lag(task_system, time_t, ps_allocations, gedf_allocations):
    total_lag = 0
    for task in task_system.tasks:
        total_lag += calculate_lag(task, time_t, ps_allocations, gedf_allocations)
    return total_lag

def calculate_instantaneous_lag(task, time_t, released_work, gedf_allocations):
    # released_work is a dictionary mapping task to total execution time of released jobs
    instantaneous_lag_i = released_work.get(task, 0) - gedf_allocations.get(task, 0)
    return instantaneous_lag_i

def calculate_total_instantaneous_lag(task_system, time_t, released_work, gedf_allocations):
    total_il = 0
    for task in task_system.tasks:
        total_il += calculate_instantaneous_lag(task, time_t, released_work, gedf_allocations)
    return total_il

def claim6_il_vs_lag(job_i_j, f_i_j, g_i_j, m, il_at_f_i_j, l_at_g_i_j):
    # This is a direct check of the inequality.
    # The proof relies on relating a_IS, a_PS, and a_GEDF.
    return il_at_f_i_j <= l_at_g_i_j + m * (g_i_j - f_i_j)

def corollary10_bound_gedf_tardiness(job_i_j, u_i, psi, E_eta_i_j, m, upsilon, E_e_i_j):
    # This function represents the calculation of the expected tardiness bound.
    # The actual calculation of E_eta_i_j and E_H_i_j would be complex.
    expected_tardiness_bound = u_i * psi + E_eta_i_j + m * (some_expected_H_i_j) / (m - upsilon) + E_e_i_j
    return expected_tardiness_bound

def corollary10_bound_quantile(expected_tardiness_bound, q):
    if q >= 1.0:
        return float('inf') # Or handle as error
    return expected_tardiness_bound / (1.0 - q)
